// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 total, uint256 part, uint256 extra) public {
        vm.assume(total <= VALUE_CAP);
        vm.assume(extra <= VALUE_CAP);
        vm.assume(total > 0);
        vm.assume(part > 0);
        vm.assume(part < total);
        vm.assume(extra > 0);

        address actor = address(0xA11CE);
        vm.deal(actor, total + extra);

        vm.prank(actor);
        c.deposit{value: total}();

        vm.prank(actor);
        c.withdraw(part);

        vm.prank(actor);
        c.deposit{value: extra}();

        vm.prank(actor);
        bool ok;
        try c.withdraw(total - part + extra) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
